 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M263','M264','M265','M266','M267','M268','M269','M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['online_alpha_end_to_end_server_contract']; assert row['status']=='PARTIAL' and 'm263_fix' in row and 'production authentication/account backend' in row['remaining'] and 'native end-to-end Online Alpha tests with limited users' in row['remaining']
